<script setup lang="ts">
import { onMounted, ref } from 'vue'
import SectionPanel from '../components/SectionPanel.vue'
import WorkspaceStickyStack from '../components/WorkspaceStickyStack.vue'
import { reportsApi, type BackupInfoRecord, type DataPathsRecord, type ShopSettingsRecord } from '../api/reports'
import { confirmAction, normalizeError } from '../ui/feedback'
const emit=defineEmits<{notify:[message:string]}>();const form=ref<ShopSettingsRecord>({shopName:'',shopSubtitle:'',phone:'',address:'',email:'',website:'',registrationId:'',taxId:'',logoPath:'',documentFooter:'',documentNotes:''});const loading=ref(true);const backupBusy=ref(false);const backupPath=ref('');const paths=ref<DataPathsRecord|null>(null);const lastBackup=ref<BackupInfoRecord|null>(null)
onMounted(async()=>{try{const [settings,dataPaths]=await Promise.all([reportsApi.settings(),reportsApi.dataPaths()]);form.value=settings;paths.value=dataPaths;try{lastBackup.value=await reportsApi.lastBackup()}catch{/* no backup yet */}}catch(e){emit('notify',String(e))}finally{loading.value=false}});async function save(){try{await reportsApi.saveSettings(form.value);emit('notify','Document identity saved.')}catch(e){emit('notify',String(e))}}
async function createBackup(){backupBusy.value=true;try{lastBackup.value=await reportsApi.createBackup();backupPath.value=lastBackup.value.path;emit('notify','Backup created and verified.')}catch(e){emit('notify',String(e))}finally{backupBusy.value=false}}
async function chooseBackup(){try{const path=await reportsApi.selectBackupFile();if(path)backupPath.value=path}catch(e){emit('notify',String(e))}}
async function verifyBackup(){if(!backupPath.value)return;backupBusy.value=true;try{lastBackup.value=await reportsApi.verifyBackup(backupPath.value);emit('notify','Backup is valid.')}catch(e){emit('notify',String(e))}finally{backupBusy.value=false}}
async function restoreBackup(){if(!backupPath.value||!(await confirmAction({title:'Restore backup',message:'Restore this backup? The current application data will be replaced after validation.',confirmLabel:'Restore backup',danger:true})))return;backupBusy.value=true;try{lastBackup.value=await reportsApi.restoreBackup(backupPath.value);emit('notify','Backup restored successfully.')}catch(e){emit('notify',normalizeError(e).message)}finally{backupBusy.value=false}}
</script>
<template><div><WorkspaceStickyStack><header><div><p>Insights & setup</p><h1>Shop settings</h1><p>Identity, data safety, and notes used by printable documents.</p></div><button class="btn btn-ghost" type="button" :disabled="loading" @click="save">Save settings</button></header></WorkspaceStickyStack><SectionPanel title="Document identity" subtitle="Logo path is metadata only; file blobs remain outside SQLite"><div><label class="form-control gap-1">Shop name<input class="input input-bordered w-full min-w-0" v-model="form.shopName"/></label><label class="form-control gap-1">Subtitle<input class="input input-bordered w-full min-w-0" v-model="form.shopSubtitle"/></label><label class="form-control gap-1">Phone<input class="input input-bordered w-full min-w-0" v-model="form.phone"/></label><label class="form-control gap-1">Email<input class="input input-bordered w-full min-w-0" v-model="form.email" type="email"/></label><label class="form-control gap-1">Website<input class="input input-bordered w-full min-w-0" v-model="form.website"/></label><label class="form-control gap-1">Logo path<input class="input input-bordered w-full min-w-0" v-model="form.logoPath"/></label><label class="form-control gap-1">Address<textarea class="textarea textarea-bordered w-full min-w-0" v-model="form.address" rows="2"/></label><label class="form-control gap-1">Registration ID<input class="input input-bordered w-full min-w-0" v-model="form.registrationId"/></label><label class="form-control gap-1">Tax ID<input class="input input-bordered w-full min-w-0" v-model="form.taxId"/></label><label class="form-control gap-1">Default footer<textarea class="textarea textarea-bordered w-full min-w-0" v-model="form.documentFooter" rows="2"/></label><label class="form-control gap-1">Default notes<textarea class="textarea textarea-bordered w-full min-w-0" v-model="form.documentNotes" rows="2"/></label></div></SectionPanel><SectionPanel title="Backup & restore" subtitle="Backups include a consistent SQLite snapshot and Atropaten-managed files"><div v-if="paths"><div><span>Data location</span><strong>{{ paths.root }}</strong></div><div><span>Database</span><strong>{{ paths.database }}</strong></div><div><span>Application / schema</span><strong>{{ paths.applicationVersion }} · v{{ paths.schemaVersion }}</strong></div><div><span>Backups folder</span><strong>{{ paths.backups }}</strong></div></div><div><button class="btn btn-ghost" type="button" :disabled="backupBusy" @click="createBackup">Create backup</button><button class="btn btn-ghost" type="button" :disabled="backupBusy||!backupPath" @click="verifyBackup">Verify selected</button><button class="btn btn-ghost" type="button" :disabled="backupBusy" @click="chooseBackup">Choose backup</button><button class="btn btn-ghost" type="button" :disabled="backupBusy||!backupPath" @click="restoreBackup">Restore selected</button></div><label class="form-control gap-1">Selected backup<input class="input input-bordered w-full min-w-0" v-model="backupPath" placeholder="Choose an .zip backup"/></label><p v-if="lastBackup">{{ lastBackup.path }} · schema v{{ lastBackup.schemaVersion }} · {{ lastBackup.managedFileCount }} managed file(s)</p></SectionPanel></div></template>
